Led Profiles).  \\n 🏛️ واجهات خارجية فاخرة: تركيب حجر ورخام للواجهات والأسوار بأعلى دقة.  \\n ⏱️ الالتزام بالوقت: تسليم في الموعد المحدد وبأعلى معايير الأمانة والجودة.\\n🎁 عرض خاص لفترة محدودة:\\nاحصل على معاينة مجانية واستشارة هندسية لتوزيع المساحات عند تعاقدك معنا هذا الشهر!\\n📞 للتواصل والاستفسار: [01065557558]\\n#Golden_Eagle #تشطيبات_وديكور #تشطيبات_مصر #تشطيب_شقق #تشطيب_مكاتب #قبل_وبعد #ديكورات_مودرن", "meta_id": "", "youtube": "", "facebook": "", "instagram": ""}', 'premium', 'engineer', 'madygroupmg'), (847, '2026-10-17 16:45:01.274166+00', '5d307a89-377b-41e4-8303-c3f753fa20c5', null, null, null, 'professional', 'engineer', 'engineermoaaz201266'), (849, '2026-10-18 04:30:45.571735+00', 'ac8ac792-36eb-4f1d-b648-ea5a9a3c1f83', null, null, null, 'basic', 'office', 'michaelmourad2015'), (851, '2026-10-19 12:11:26.164993+00', 'b2a93075-6e04-45e0-b92c-40312cc3c0d6', '{"image": "https://res.cloudinary.com/drk3bhviw/image/upload/v1792420073/%D8%A8%D8%A7%D9%86%D8%B1_%D9%81%D8%A7%D8%AE%D8%B1_%D9%84%D9%84%D8%AA%D8%B5%D9%85%D9%8A%D9%85_%D8%A7%D9%84%D8%AF%D8%A7%D8%AE%D9%84%D9%8A_%D9%88%D9%85%D8%AE%D8%B7%D8%B7%D8%A7%D8%AA_%D9%85%D8%B9%D9%85%D8%A7%D8%B1%D9%8A%D8%A9_fxlzgi.webp", "title": "", "description": ""}', null, null, 'premium', 'office', 'engmennatallah'), (853, '2026-10-19 12:36:32.4333+00', '2d9f3353-c64a-42b5-b866-da81130b9b94', null, null, null, 'basic', 'office', 'georgeesame'), (855, '2026-10-19 19:51:15.761738+00', '66b13843-844d-419d-9752-d50b360fb298', '{"image": "https://res.cloudinary.com/drk3bhviw/image/upload/v1792440443/%D8%A5%D8%B9%D9%84%D8%A7%D9%86_%D8%A5%D8%B1%D9%85_%D9%84%D9%84%D8%AA%D8%B5%D9%85%D9%8A%D9%85_%D9%88%D8%A7%D9%84%D8%A5%D9%86%D8%B4%D8%A7%D8%A1%D8%A7%D8%AA_y1neqj.webp", "title": "", "description": ""}', null, null, 'premium', 'office', 'engammarmhmd'), (859, '2026-10-19 20:46:09.944901+00', '480743ec-18a6-4a79-9187-b4eafab1d33a', null, null, null, 'basic', 'engineer', 'mariamelazazy97'), (861, '2026-10-19 21:16:14.02568+00', 'cc6df287-0